 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Separator lines divide the picture into equal panels; boundaries are
    # color 5 (the demo uses 8). Infer the separator color from the grid.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    separator = max((v for v in counts if v != 0), key=lambda v: counts[v])
    row_bounds = [i for i, row in enumerate(grid) if all(v == separator for v in row)]
    col_bounds = [j for j in range(w) if all(grid[i][j] == separator for i in range(h))]
    row_edges = [-1] + row_bounds + [h]
    col_edges = [-1] + col_bounds + [w]
    panels = []
    for ri in range(len(row_edges) - 1):
        r0, r1 = row_edges[ri] + 1, row_edges[ri + 1]
        if r0 >= r1:
            continue
        for ci in range(len(col_edges) - 1):
            c0, c1 = col_edges[ci] + 1, col_edges[ci + 1]
            if c0 < c1:
                panels.append((ri, ci, r0, r1, c0, c1))
    # Find the patterned panel: the unique panel that is not a solid 2x2
    # marker (ordinary panels have a 2x2 colored square in their upper-left).
    source = None
    for ri, ci, r0, r1, c0, c1 in panels:
        cells = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
        nonzero = [v for v in cells if v != 0]
        if len(nonzero) > 4:
            source = (r0, r1, c0, c1, nonzero[0])
            break
    if source is None:
        return [row[:] for row in grid]
    sr0, sr1, sc0, sc1, pattern_color = source
    pattern = [[grid[r][c] == pattern_color for c in range(sc0, sc1)] for r in range(sr0, sr1)]
    out = [row[:] for row in grid]
    # Color for each horizontal band is the marker color in its leftmost panel.
    band_colors = {}
    for ri, ci, r0, r1, c0, c1 in panels:
        if ci == 0:
            band_colors[ri] = next((grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] not in (0, separator)), 0)
    for ri, ci, r0, r1, c0, c1 in panels:
        color = band_colors.get(ri, 0)
        for dr in range(r1 - r0):
            for dc in range(c1 - c0):
                out[r0 + dr][c0 + dc] = color if pattern[dr][dc] else 0
    return out

if __name__ == '__main__':
    pass
